"""ERR-01 migration of the legacy CRMScript division semantics."""

from __future__ import annotations

from typing import Any


def _legacy_number(value: Any) -> float:
    """Coerce a supported legacy numeric value to float."""
    if value is None:
        return 0.0
    if isinstance(value, str):
        if value == "":
            return 0.0
        return float(value)
    return float(value)


def safe_div(a: Any, b: Any) -> tuple[float, list[str]]:
    """Perform legacy numeric division, auditing division by zero."""
    numerator = _legacy_number(a)
    denominator = _legacy_number(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    return numerator / denominator, []
